#!/bin/bash
set -e

# Invoice Modification rebuilt to mirror New Invoice's full layout:
# patient name + visit shown locked, original line items locked
# (Dept/Rate/Disc/Net columns now visible, not just Service/Qty/Net),
# Surgery Billing Details section added (editable, same as New Invoice),
# Add Line Item department list unified with New Invoice's full list.
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "app/(main)/billing"
echo "" | base64 -d > "app/(main)/billing/actions.js"
echo "Wrote app/(main)/billing/actions.js"

mkdir -p "app/(main)/billing/cancel"
echo "" | base64 -d > "app/(main)/billing/cancel/invoice-modification-tab.js"
echo "Wrote app/(main)/billing/cancel/invoice-modification-tab.js"

git add "app/(main)/billing/actions.js" "app/(main)/billing/cancel/invoice-modification-tab.js"
git commit -m "Rebuild Invoice Modification to mirror New Invoice layout with locks"
git push

echo "Done."
